// Pure self-check of our own generated feed XML — what Feed overview reports as
// "Podcast 1.0" / "Podcasting 2.0" status. It is NOT Apple's or Spotify's
// validator: it only tests for tags those directories require and Podstudio can
// read back from the XML it just wrote. The feed is machine-generated by
// feed-xml.ts / item-xml.ts, so plain text matching is enough here.

/** A problem plus where in the studio it is fixed (so the UI can link straight there). */
export interface FeedIssue {
  message: string;
  fix: { label: string; to: string };
}

export interface FeedCheck {
  items: number;
  errors: FeedIssue[];
  warnings: FeedIssue[];
  /** Podcasting 2.0 tags present in the feed, by name. */
  podcast20: string[];
}

const POD20 = [
  "guid",
  "locked",
  "person",
  "funding",
  "medium",
  "updateFrequency",
  "license",
  "txt",
  "podroll",
  "value",
  "trailer",
  "transcript",
  "chapters",
  "soundbite",
  "alternateEnclosure",
] as const;
export const POD20_TOTAL = POD20.length;

const TAGS = (label: string, anchor = "") => ({ label, to: `/studio/feed/tags${anchor}` });
const EPISODES = { label: "Podcast hosting → Episodes", to: "/studio/episodes" };

function has(xml: string, tag: string) {
  return new RegExp(`<${tag}[\\s>/]`).test(xml);
}

export function checkFeed(xml: string): FeedCheck {
  const firstItem = xml.indexOf("<item>");
  const channel = firstItem === -1 ? xml : xml.slice(0, firstItem);
  const items = xml.split("<item>").slice(1);
  const errors: FeedIssue[] = [];
  const warnings: FeedIssue[] = [];

  for (const [tag, why, anchor] of [
    ["title", "show title", "#title"],
    ["link", "show link", "#website"],
    ["description", "show description", "#description"],
    ["language", "language", "#language"],
    ["itunes:explicit", "explicit flag", "#explicit"],
  ] as const) {
    if (!has(channel, tag)) errors.push({ message: `Missing ${why}.`, fix: TAGS("Podcast hosting → Show tags", anchor) });
  }
  if (!has(channel, "itunes:image")) {
    errors.push({
      message: "Missing show artwork (itunes:image) — Apple and Spotify require it.",
      fix: TAGS("Podcast hosting → Show tags → Show artwork", "#artwork"),
    });
  }
  if (!has(channel, "itunes:category")) {
    errors.push({
      message: "Missing category (itunes:category) — Apple requires it.",
      fix: TAGS("Podcast hosting → Show tags → Category", "#category"),
    });
  }
  if (!has(channel, "itunes:author")) {
    warnings.push({ message: "No author set (itunes:author).", fix: TAGS("Podcast hosting → Show tags → Author", "#author") });
  }

  if (items.length === 0) warnings.push({ message: "No episodes in the feed yet.", fix: EPISODES });
  items.forEach((item, i) => {
    const t = item.match(/<title>([^<]*)<\/title>/)?.[1] || `item ${i + 1}`;
    for (const tag of ["title", "guid", "pubDate"]) {
      if (!has(item, tag)) errors.push({ message: `“${t}” is missing <${tag}>.`, fix: EPISODES });
    }
    const enc = item.match(/<enclosure\b[^>]*>/)?.[0];
    if (!enc || !/url="[^"]+"/.test(enc) || !/length="\d+"/.test(enc) || !/type="[^"]+"/.test(enc)) {
      errors.push({ message: `“${t}” has no valid <enclosure>.`, fix: EPISODES });
    }
    if (!has(item, "itunes:duration")) warnings.push({ message: `“${t}” has no itunes:duration.`, fix: EPISODES });
  });

  return { items: items.length, errors, warnings, podcast20: POD20.filter((n) => has(xml, `podcast:${n}`)) };
}
